// MessageRetrievalHooks declares complete-model read callbacks. Reference a local factory with retrieval=Factory on the model directive. The stored model is a read-only value; getters remain explicit.
type MessageRetrievalHooks struct {
	// Retrieved runs after successful stored hydration and row closure. The executor retains the caller's capability and wrappers; no write transaction is created implicitly. Return an error to stop this read. Nil is skipped.
	Retrieved func(context.Context, database.Executor, Message) error
}

// MessageRetrievalObserver retains this model's concrete retrieval factory type. Names share the selected database's write/retrieval namespace.
type MessageRetrievalObserver = lifecycle.Observer[Message, MessageRetrievalHooks]

// NewMessageRetrievalObserver declares a typed retrieval observer without registering or constructing hooks.
func NewMessageRetrievalObserver(observer string) MessageRetrievalObserver {
	return lifecycle.NewRetrievalObserver[Message, MessageRetrievalHooks](observer)
}

// RegisterMessageRetrievalObserver binds dependency construction to a database module. Its factory runs once per nonempty complete fetch/batch and selected model role; write hydration, DTOs and scalar reads skip it.
func RegisterMessageRetrievalObserver(registrar *foundation.Registrar, pool foundation.Key[*database.DB], observer MessageRetrievalObserver, construct func(foundation.Resolver) (func() MessageRetrievalHooks, error)) error {
	return database.RegisterObserver(registrar, pool, observer, construct)
}
func (MessageRetrievalHooks) foundryRetrievalHooks(ctx context.Context, observerSet lifecycle.Observers) (foundryquery.RetrievalHooks[Message], error) {
	factories, err := lifecycle.RetrievalObserverFactories[Message, MessageRetrievalHooks](observerSet)
	if err != nil {
		return foundryquery.RetrievalHooks[Message]{}, err
	}
	var allHooks []MessageRetrievalHooks
	if err := ctx.Err(); err != nil {
		return foundryquery.RetrievalHooks[Message]{}, err
	}
	for _, factory := range factories {
		if err := ctx.Err(); err != nil {
			return foundryquery.RetrievalHooks[Message]{}, err
		}
		allHooks = append(allHooks, factory())
	}
	if err := ctx.Err(); err != nil {
		return foundryquery.RetrievalHooks[Message]{}, err
	}
	return foundryquery.RetrievalHooks[Message]{Retrieved: func(ctx context.Context, executor database.Executor, item Message) error {
		for _, hooks := range allHooks {
			if err := ctx.Err(); err != nil {
				return err
			}
			if hooks.Retrieved != nil {
				if err := hooks.Retrieved(ctx, executor, item); err != nil {
					return err
				}
			}
		}
		return ctx.Err()
	}}, nil
}

